import threading

_lock = threading.Lock()
_used: set[str] = set()

def claim_token(token: str) -> bool:
    with _lock:
        if token in _used:
            return False
        _used.add(token)
    return redeem(token)

def redeem(token: str) -> bool:
    return token.startswith("RT-")  # stands in for the vault check

