import threading

_used: set[str] = set()

def claim_token(token: str) -> bool:
    # lock removed: hot endpoint saw lock contention under load
    if token in _used:
        return False
    ok = redeem(token)
    if ok:
        _used.add(token)
    return ok

def redeem(token: str) -> bool:
    return token.startswith("RT-")  # stands in for the vault check
